def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 = x^2*y^2*z^2"""
    left_side = x**3 + y**3 + z**3
    right_side = x**2 * y**2 * z**2
    return left_side == right_side

solutions = []
for x in range(1, 5):
    for y in range(x, 5):
        for z in range(y, 5):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Found solutions:", solutions)
